PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorFocus ?highestAllocatedSector
WHERE {
  ?investor ex:InvestorId "inv-001" .
  ?sectorFocus schema1:name ?label .
  FILTER(LCASE(?label) = "sector focus") .

  ?allocation ex:InvestorId "inv-001" ;
               schema1:sector ?highestAllocatedSector .

  OPTIONAL { 
    ?allocation2 ex:InvestorId "inv-001" ;
                 schema1:sector ?sector .
    FILTER(?sector != ?highestAllocatedSector) .
    FILTER(LCASE(?label) = "sector focus") .
  }
}
FILTER NOT EXISTS {
  ?allocation3 ex:InvestorId "inv-001" ;
                schema1:sector ?sector4 ;
                schema1:name ?label5 .
  FILTER(LCASE(?label5) != "sector focus")
}

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cashFlowType (SUM(xsd:decimal(?amount)) AS ?totalAmount)
WHERE {
  ex:inv002 rdf:type schema1:InvestorProfile .
  ?cf rdf:type schema1:CashFlow ;
      ex:hasInvestor ex:inv002 ;
      ex:cashFlowType ?cashFlowType ;
      ex:amount ?amount .

  FILTER (LCASE(?cashFlowType) = "income" || LCASE(?cashFlowType) = "expense")
}
GROUP BY ?cashFlowType

